    @classmethod
    def get(cls, key: str, default: str = None) -> str:
        lang_dict = cls.DICTIONARY.get(cls.CURRENT_LANG, cls.DICTIONARY["zh_CN"])
        val = lang_dict.get(key)
        if val is not None:
            return val
        
        # Fallback 1: English
        en_dict = cls.DICTIONARY.get("en_US", {})
        val = en_dict.get(key)
        if val is not None:
            return val
            
        # Fallback 2: Chinese
        zh_dict = cls.DICTIONARY.get("zh_CN", {})
        val = zh_dict.get(key)
        if val is not None:
            return val
            
        return default or key
